import java.util.*;

public class Main {
    static void bump(int x) { x = x + 1; }              // changes only the copy
    static void mutate(int[] a) { a[0] = 99; }          // copy of address, same array
    static void reassign(int[] a) { a = new int[]{7, 7, 7}; } // only the copy changes
    public static void main(String[] args) {
        int n = 5;
        bump(n);
        System.out.println("int after bump: " + n);
        int[] arr = {1, 2, 3};
        System.out.println("before: " + Arrays.toString(arr));
        mutate(arr);
        System.out.println("after mutate: " + Arrays.toString(arr));
        reassign(arr);
        System.out.println("after reassign: " + Arrays.toString(arr));
        // Output shows: values copied, arrays changed through the copy only
    }
}

public class Main {
    // Count digits with while: 0 gives 0 digits (wrong for 0)
    static int digitsWhile(int n) {
        int c = 0;
        while (n > 0) { c++; n /= 10; }
        return c;
    }
    // do-while runs the body once first, so 0 has 1 digit
    static int digitsDo(int n) {
        int c = 0;
        do { c++; n /= 10; } while (n > 0);
        return c;
    }
    public static void main(String[] args) {
        int[] tests = {0, 7, 12345};
        for (int t : tests) {   // for-each reads every element
            System.out.println(t + ": while=" + digitsWhile(t) + " do-while=" + digitsDo(t));
        }
        // for(;;) with no condition loops until break
        int k = 0;
        for (;;) { if (++k == 3) break; }
        System.out.println("for(;;) stopped at " + k);
    }
}

public class Main {
    static String oldStyle(int x) {
        String s = "";
        switch (x) {
            case 1: s += "one ";      // no break: falls into case 2
            case 2: s += "two ";
                break;
            case 4: case 6: s += "grouped "; // deliberate grouping
                break;
            default: s += "other ";
        }
        return s.trim();
    }
    static String arrow(int x) {
        switch (x) {
            case 1 -> { return "one"; }        // never falls through
            case 2 -> { return "two"; }
            case 4, 6 -> { return "grouped"; } // several labels in one branch
            default -> { return "other"; }
        }
    }
    public static void main(String[] args) {
        for (int x : new int[]{1, 2, 4, 9}) {
            System.out.println(x + " old=[" + oldStyle(x) + "] arrow=[" + arrow(x) + "]");
        }
    }
}

public class Main {
    static int days(int m) {
        // switch expression: yields a value, no fall-through
        return switch (m) {
            case 2 -> 28;
            case 4, 6, 9, 11 -> 30;
            default -> 31;
        };
    }
    static String describe(Object o) {
        // pattern matching for switch, with null handled explicitly
        return switch (o) {
            case null -> "null";
            case Integer i when i > 10 -> "big int " + i;
            case Integer i -> "int " + i;
            case String s -> "string of length " + s.length();
            default -> "something else";
        };
    }
    public static void main(String[] args) {
        System.out.println("days(2)=" + days(2) + " days(6)=" + days(6) + " days(7)=" + days(7));
        Object[] items = {5, 42, "hello", null, 3.5};
        for (Object o : items) System.out.println(o + " -> " + describe(o));
    }
}

public class Main {
    static int code(String s) {
        switch (s) {              // compiled as hashCode() switch, then equals()
            case "red": return 1;
            case "green": return 2;
            default: return 0;
        }
    }
    public static void main(String[] args) {
        System.out.println("red -> " + code("red"));
        System.out.println("blue -> " + code("blue"));
        char c = 'b';             // char widens to int, so it is allowed
        switch (c) {
            case 'a': System.out.println("a"); break;
            case 'b': System.out.println("char b matched"); break;
        }
        try {
            code(null);
        } catch (NullPointerException e) {
            System.out.println("null String in classic switch -> NullPointerException");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int[][] g = {{1, 2, 3}, {4, 0, 6}, {7, 8, 9}};
        int target = 6;
        // break outer leaves BOTH loops at the first hit
        search:
        for (int r = 0; r < g.length; r++) {
            for (int c = 0; c < g[r].length; c++) {
                if (g[r][c] == target) {
                    System.out.println("found " + target + " at (" + r + "," + c + ")");
                    break search;
                }
            }
        }
        // continue outer skips the rest of a row once a 0 is seen
        int sum = 0;
        rows:
        for (int[] row : g) {
            for (int v : row) {
                if (v == 0) continue rows; // next row, running the outer update
                sum += v;
            }
        }
        System.out.println("sum of rows without zeros partial = " + sum);
    }
}

public class Main {
    static class Animal { String sound() { return "..."; } }
    static class Dog extends Animal { @Override String sound() { return "woof"; } }
    static void print(Object o) { System.out.println("print(Object)"); }
    static void print(String s) { System.out.println("print(String)"); }
    public static void main(String[] args) {
        Object o = "hi";
        String s = "hi";
        print(o);   // overload chosen at compile time from the static type Object
        print(s);   // static type String
        Animal a = new Dog();
        System.out.println(a.sound()); // override chosen at run time: Dog's body
        // int f() and long f() in one class would not compile (return type alone)
    }
}

import java.util.*;

public class Main {
    static void f(long x) { System.out.println("f(long)"); }
    static void f(Integer x) { System.out.println("f(Integer)"); }
    static void f(int... x) { System.out.println("f(int...)"); }
    public static void main(String[] args) {
        f(5);   // phase 1 (widening) finds f(long) before boxing is tried
        f(Integer.valueOf(5)); // exact match f(Integer)
        f();    // only varargs applies
        List<Integer> list = new ArrayList<>(List.of(10, 1, 5));
        System.out.println("list: " + list);
        list.remove(1);                     // remove(int index) wins in phase 1
        System.out.println("after remove(1): " + list);
        list.remove(Integer.valueOf(5));    // remove(Object) removes by value
        System.out.println("after remove(Integer 5): " + list);
    }
}

import java.util.*;

public class Main {
    static int sum(int... xs) {          // xs is an int[]
        int t = 0;
        for (int x : xs) t += x;
        return t;
    }
    static int max(int first, int... rest) { // forces at least one value
        int m = first;
        for (int x : rest) m = Math.max(m, x);
        return m;
    }
    public static void main(String[] args) {
        System.out.println("sum() = " + sum());
        System.out.println("sum(1,2,3) = " + sum(1, 2, 3));
        System.out.println("sum(array) = " + sum(new int[]{4, 5}));
        System.out.println("max(3,9,4) = " + max(3, 9, 4));
        int[] prim = {1, 2, 3};
        System.out.println("asList(int[]).size() = " + Arrays.asList(prim).size()); // 1
        Integer[] boxed = {1, 2, 3};
        System.out.println("asList(Integer[]).size() = " + Arrays.asList(boxed).size()); // 3
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[][] tri = new int[4][];            // rows not created yet are null
        System.out.println("row 0 before: " + tri[0]);
        for (int i = 0; i < tri.length; i++) {
            tri[i] = new int[i + 1];           // each row is its own array
            Arrays.fill(tri[i], i);
        }
        System.out.println(Arrays.deepToString(tri));
        int[][] shallow = tri.clone();         // copies row references only
        shallow[1][0] = 99;
        System.out.println("original sees change: " + tri[1][0]);
        int[][] deep = new int[tri.length][];
        for (int i = 0; i < tri.length; i++) deep[i] = tri[i].clone();
        deep[2][0] = -1;
        System.out.println("deep copy isolated: " + tri[2][0]);
        System.out.println("toString: " + Arrays.toString(tri).substring(0, 3) + "...");
    }
}

