import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Object[] objs = new String[2];         // arrays are covariant
        try {
            objs[0] = 42;                      // compiles, fails at run time
        } catch (ArrayStoreException e) {
            System.out.println("ArrayStoreException: " + e.getMessage());
        }
        List<Integer> list = new ArrayList<>(); // grows automatically, boxes ints
        for (int i = 1; i <= 5; i++) list.add(i * i);
        System.out.println("list = " + list);
        int[] prim = list.stream().mapToInt(Integer::intValue).toArray();
        System.out.println("int[] = " + Arrays.toString(prim));
        List<Integer> back = Arrays.stream(prim).boxed().collect(Collectors.toList());
        System.out.println("back to list = " + back);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] arr = {"a", "b", "c"};
        List<String> view = Arrays.asList(arr);    // view backed by the array
        view.set(0, "X");
        System.out.println("array after set: " + Arrays.toString(arr));
        try { view.add("d"); } catch (UnsupportedOperationException e) {
            System.out.println("asList add -> UnsupportedOperationException");
        }
        List<String> imm = List.of("a", "b");      // immutable, no nulls
        try { imm.add("z"); } catch (UnsupportedOperationException e) {
            System.out.println("List.of add -> UnsupportedOperationException");
        }
        try { List.of("a", null); } catch (NullPointerException e) {
            System.out.println("List.of with null -> NullPointerException");
        }
        List<String> copy = new ArrayList<>(view); // independent and mutable
        copy.add("d");
        arr[1] = "Y";
        System.out.println("copy = " + copy + ", view = " + view);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        String[] words = {"pear", "fig", "apple", "kiwi", "plum"};
        // TimSort for objects is stable: equal lengths keep input order
        Arrays.sort(words, Comparator.comparingInt(String::length));
        System.out.println("by length (stable): " + Arrays.toString(words));
        Integer[] nums = {3, 1, 2};
        Arrays.sort(nums, Collections.reverseOrder()); // descending needs Integer[]
        System.out.println("descending: " + Arrays.toString(nums));
        int a = Integer.MAX_VALUE, b = -1;
        System.out.println("a - b = " + (a - b) + " (overflow, wrong sign)");
        System.out.println("Integer.compare = " + Integer.compare(a, b)); // correct
        int[] prim = {5, 2, 9, 1};
        Arrays.sort(prim);                             // dual-pivot quicksort
        System.out.println("primitives: " + Arrays.toString(prim));
    }
}

public class Main {
    public static void main(String[] args) {
        String s = "hello";
        s.toUpperCase();                    // result thrown away
        System.out.println("after toUpperCase(): " + s);
        s = s.toUpperCase();                // keep the new String
        System.out.println("after assignment: " + s);
        System.out.println("substring(1,3) = " + "abcdef".substring(1, 3)); // end excluded
        System.out.println("indexOf missing = " + "abc".indexOf('z'));
        System.out.println("split(\".\") length = " + "a.b".split(".").length);
        System.out.println("split(\"\\\\.\") length = " + "a.b".split("\\.").length);
        // += in a loop copies the text each time: O(n^2); StringBuilder is O(n)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 5; i++) sb.append(i);
        System.out.println("StringBuilder = " + sb);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        String a = "java";
        String b = new String("java");      // different object, same text
        System.out.println("a == b: " + (a == b));
        System.out.println("a.equals(b): " + a.equals(b));
        String n = null;
        System.out.println("\"java\".equals(null var): " + "java".equals(n)); // safe
        System.out.println("abc vs abd: " + "abc".compareTo("abd"));
        System.out.println("apple vs app: " + "apple".compareTo("app"));
        System.out.println("B vs a: " + "B".compareTo("a"));
        String[] w = {"banana", "Apple", "cherry"};
        Arrays.sort(w);
        System.out.println("default: " + Arrays.toString(w));
        Arrays.sort(w, String.CASE_INSENSITIVE_ORDER);
        System.out.println("ignore case: " + Arrays.toString(w));
    }
}
